window.GALLERY_POSTS = {"Dd7YIGuiNE-":{"c":"Ночуем одни на парковке у озера Берцдорфер-Зе (Berzdorfer See)🇩🇪\n\nОзеро находится прямо возле границы с Польшей и известным городом Згожелец, но с немецкой стороны.\n\nВокруг озера проложена полноценная велодорожка длиной 18 километров.\n\nНу и, конечно, с разных сторон озера открываются невероятные пейзажи!"},"Dd4957GiMcg":{"c":"Zittau 🇩🇪"},"Ddv0SfGCIRK":{"c":"Гора Снежка 🏔️ \nВысота 1600 метров располагается на границе Польша - Чехия. На самой вершине можно переходить из одного государства в другое🙃"},"DdUQcx3COgr":{"c":"Дом на колесах дает возможность пожить несколько дней на одной локации и исследовать округи на велосипеде, яем я собственно и занялся. \n\nПервый поселок на чешской стороне  называется:\nМАЛА УПА, как будто троллят поляков этим названием. \n\nА вообще до границы с Чехией было всего 13км подьема вечного, с набором высоты 500 метров над уровнем моря. \n\nДоехав туда, там не было никаких полицейских которые бы охраняли границу. \n\nНо знак Ческая республика был угандошан наклейками и никто его не чистит. \n\nВиды с Чешской стороны.\nMALA UPA 🇨🇿\n\nИнтересно сколько лет домикам 👀\n\nПроехав километр от границы, есть лавочка с таким прекрасным видом на гору СНЕЖКА \nВысота которой составляет 1600м над уровнем моря. \n\nВершина СНЕЖКИ \n\nМой дрыпчик на котором взбирался на гору. \n\nА я находился на высоте 1050 над уровнем моря."},"DdOwNjIiCZ9":{"c":"Инстаграмная жизнь в автодоме 🗿\nПольша.несколько километров на вело и граница с Чехией."},"DcLkgToiPtz":{"c":"Wodny Świat 🐠"},"DcGeJIGCKsn":{"c":"🌼"},"DbVtqT9CJUd":{"c":"Gdynia 🇵🇱"},"DarJbDeiOnL":{"c":"Gdańsk 🇵🇱"},"DaVcnhPCPyE":{"c":"Замена главной платы на фотике #fujifilm xt4, обошлась всего в 160€ и теперь можно снова делать кадры на лево и на право. \nНа фото Италия, сняла с кабины грузовика на ходу."},"DaSz3ZxCAEg":{"c":"Ноу фильтрес енд эдишенс"},"DZwEyNvCNVp":{"c":"Sunrise 🌅"},"DYR-HuJCF-W":{"c":"🇩🇪🇩🇪🇩🇪"},"DU1kuIiCOkR":{"c":"Szczecin luty"},"DUHYrzoCBPT":{"c":"Зима должна быть только со снегом. \nБез снега - это затяжная осень."},"DTXyxQpCHor":{"c":"автодом и зимний лес."},"DS8nrOsiNeq":{"c":"Happy New year 🐲2026"},"DShc2SzCI8A":{"c":"лови каждый закат 🌅"},"DSVA5ayiNG-":{"c":"море в средине декабря такое же прекрасное, но невероятно холодное 🌊"},"DRHWoQbiGgQ":{"c":"и пускай небо будет ярким, а птицы свободны"},"DQ2dOkVCLVo":{"c":"красивые закаты, остались позади. \nвпереди ожидаемся серость, туман и дожди 🌧️"},"DQuLGoxiIxl":{"c":"Kołobrzeg 🇵🇱\n06|11|2025 ✨"},"DQriu57CLj6":{"c":"Kołobrzeg 🇵🇱"},"DQpI3gciPqG":{"c":"В вроцлавском зоопарке, не только звери есть, но и террариум с океанариумом, вход всего 80 злотых, время обхода всего зоопарка занимает 5-8 часов, смотря как быстро будете ходить по нему."},"DQeAlUGiEBI":{"c":"🐟"},"DQbnHSwiMIB":{"c":"Wrocław Zoo"},"DPodL2fiG1C":{"c":"Легница, небольшой городок в Польше, с интересной историей, ранее принадлежавший Германии, но после второй мировой, отошел в руки Польши, долгое время здесь находились советские военные и их семьи, в количестве ~80.000, в то время в городе действовали советские школы, кинотеатры, магазины где полякам вход был запрещен. Последние советские войска покинули город в 1993 году."},"DOeS77biKrx":{"c":"Gorzów wielkopolski 🇵🇱"},"DOOrpPPCJSP":{"c":"Довольно симпатичный городок, там где стоит 33х метровый Иисус. \nНо поедем дальше смотреть Польшу."},"DON3CWmCN-u":{"c":"В Польском городке Świebodzin установлен 33х метровый Иисус.\n33 метра - это отсылка к его возрасту на момент смерти.\n\nЗолочёная корона на голове статуи добавляет еще 3 метра, что делает общую высоту фигуры с короной 36 метров.\n\nСтатуя установлена на искусственно насыпанном холме высотой около 16–16,5 метров, вследствие чего общая высота конструкции — 52,5 метра от уровня земли до вершины короны."},"DOGfkudCDAb":{"c":"Gorzów Wielkopolski 🇵🇱"},"DODtFEoCA45":{"c":"Первая точка ночевки в дороге, маленький городок Lipiany 🇵🇱\nИз интересного вышка и полуостров среди озера."}};
